export const HOA12_CHUONG8_HANDBOOK = [{"title":"1. Kim Loại Chuyển Tiếp Dãy Thứ Nhất (21Sc → 30Zn)","icon":"🌌","content":["Cấu hình electron nguyên tử: [Ar]3d<sup>1-10</sup>4s<sup>1-2</sup>. Hai trường hợp đặc biệt: Cr ([Ar]3d<sup>5</sup>4s<sup>1</sup>) và Cu ([Ar]3d<sup>10</sup>4s<sup>1</sup>).","Có nhiều trạng thái oxi hóa (do có thể nhường cả electron 4s và 3d).","Hầu hết các ion và hợp chất có màu sắc đặc trưng do sự chuyển dịch electron giữa các orbital d chia tách năng lượng."]},{"title":"2. Khái Niệm & Cấu Tạo Phức Chất","icon":"🔮","content":["<b>Nguyên tử/ion trung tâm (M):</b> Thường là ion kim loại chuyển tiếp có orbital trống (Cu<sup>2+</sup>, Fe<sup>2+</sup>, Fe<sup>3+</sup>, Ag<sup>+</sup>, Pt<sup>2+</sup>...).","<b>Phối tử (L):</b> Phân tử hoặc ion có cặp electron tự do chưa liên kết (H<sub>2</sub>O, NH<sub>3</sub>, Cl<sup>-</sup>, OH<sup>-</sup>, CN<sup>-</sup>...).","<b>Số phối trí:</b> Số liên kết cho - nhận mà hạt trung tâm tạo được với các phối tử.","<b>Ví dụ:</b> [Cu(H<sub>2</sub>O)<sub>6</sub>]<sup>2+</sup> (xanh lam nhạt), [Cu(NH<sub>3</sub>)<sub>4</sub>(H<sub>2</sub>O)<sub>2</sub>]<sup>2+</sup> (xanh lam thẫm), [Ag(NH<sub>3</sub>)<sub>2</sub>]<sup>+</sup> (không màu)."]},{"title":"3. Dạng Hình Học & Ứng Dụng Của Phức Chất","icon":"✨","content":["<b>Dạng hình học:</b> Đường thẳng (số phối trí 2, ví dụ [Ag(NH<sub>3</sub>)<sub>2</sub>]<sup>+</sup>); Vuông phẳng hoặc Tứ diện (số phối trí 4, ví dụ cisplatin [Pt(NH<sub>3</sub>)<sub>2</sub>Cl<sub>2</sub>]); Bát diện (số phối trí 6, ví dụ [Fe(H<sub>2</sub>O)<sub>6</sub>]<sup>3+</sup>).","<b>Ứng dụng:</b> Thuốc chữa ung thư (cisplatin), thuốc thử phân tích hóa học (Tollens, Fehling), xúc tác chuyển hóa dầu khí, phức che giấu ion kim loại nặng EDTA."]}];

// ============================================================================
// HỆ THỐNG QUẢN LÝ TIẾN ĐỘ & GAMIFICATION LOCALSTORAGE
// ============================================================================
const STORAGE_PREFIX = 'hoa12_c8_';

export interface Chuong8ExamAttempt {
  id: string;
  examId: string;
  examTitle: string;
  score: number;
  part1Score: number;
  part2Score: number;
  part3Score: number;
  correctCount: number;
  totalQuestions: number;
  durationSeconds: number;
  tabSwitchCount: number;
  autoSubmittedDueToViolation?: boolean;
  date: string;
  formattedDate: string;
  answers: Record<string | number, any>;
}

export interface Chuong8UserProgress {
  completedLessons: string[];
  examAttempts: Record<string, Chuong8ExamAttempt[]>;
  highestScores: Record<string, number>;
  totalTimeSpentSeconds: number;
  bookmarks: string[];
  streakDays: number;
  lastActiveDate: string;
  xpPoints: number;
}

export function getChuong8UserProgress(): Chuong8UserProgress {
  try {
    const saved = localStorage.getItem(`${STORAGE_PREFIX}user_progress`);
    if (saved) return JSON.parse(saved);
  } catch (e) {
    console.error('Error loading Chuong 8 progress:', e);
  }
  return {
    completedLessons: [],
    examAttempts: {},
    highestScores: {},
    totalTimeSpentSeconds: 0,
    bookmarks: [],
    streakDays: 1,
    lastActiveDate: new Date().toISOString(),
    xpPoints: 0
  };
}

export function calculateChuong8ExamScore(questionsInput: any, userAnswers: Record<string | number, any>) {
  const questions: Chuong8Question[] = Array.isArray(questionsInput) 
    ? questionsInput 
    : (questionsInput?.questions || []);

  if (!questions || questions.length === 0) {
    return { totalScore: 0, part1Score: 0, part2Score: 0, part3Score: 0, correctCount: 0, totalQuestions: 0 };
  }

  let part1Score = 0;
  let part2Score = 0;
  let part3Score = 0;
  let correctCount = 0;

  questions.forEach(q => {
    const ans = userAnswers[q.id] || userAnswers[q.number] || userAnswers[q.displayNumber];
    if (ans === undefined || ans === null) return;

    if (q.part === 1) {
      const userLetter = typeof ans === 'string' ? ans.toUpperCase().trim() : '';
      const correctLetter = (q.correctAnswer || '').toUpperCase().trim();
      const matchedOpt = q.options?.find(o => o.isCorrect)?.letter?.toUpperCase()?.trim();
      if ((correctLetter && userLetter === correctLetter) || (matchedOpt && userLetter === matchedOpt)) {
        part1Score += 0.25;
        correctCount += 1;
      }
    } else if (q.part === 2) {
      if (typeof ans === 'object' && ans !== null) {
        let correctSubCount = 0;
        ['a', 'b', 'c', 'd'].forEach(subKey => {
          const userSubVal = ans[subKey];
          if (userSubVal === undefined || userSubVal === null) return;
          const opt = q.options?.find(o => o.letter?.toLowerCase() === subKey);
          if (opt && opt.isCorrect !== undefined) {
            const actualBool = Boolean(opt.isCorrect);
            const userBool = (userSubVal === true || userSubVal === 'true' || userSubVal === 'Đúng' || userSubVal === 'dung');
            if (actualBool === userBool) correctSubCount += 1;
          }
        });
        if (correctSubCount === 1) part2Score += 0.1;
        else if (correctSubCount === 2) part2Score += 0.25;
        else if (correctSubCount === 3) part2Score += 0.5;
        else if (correctSubCount === 4) {
          part2Score += 1.0;
          correctCount += 1;
        }
      }
    } else if (q.part === 3) {
      const userText = String(ans).trim().toLowerCase().replace(',', '.');
      const correctText = String(q.correctAnswer || '').trim().toLowerCase().replace(',', '.');
      if (correctText && userText === correctText) {
        part3Score += 0.5;
        correctCount += 1;
      }
    }
  });

  const totalScore = Math.min(10, Math.round((part1Score + part2Score + part3Score) * 100) / 100);
  return {
    totalScore,
    part1Score: Math.round(part1Score * 100) / 100,
    part2Score: Math.round(part2Score * 100) / 100,
    part3Score: Math.round(part3Score * 100) / 100,
    correctCount,
    totalQuestions: questions.length
  };
}

export function getChuong8ExamHistory(examId?: string): Chuong8ExamAttempt[] {
  try {
    const key = examId ? `${STORAGE_PREFIX}history_${examId}` : `${STORAGE_PREFIX}history_all`;
    const saved = localStorage.getItem(key);
    return saved ? JSON.parse(saved) : [];
  } catch (e) {
    return [];
  }
}

export function saveChuong8ExamAttempt(attempt: Chuong8ExamAttempt) {
  try {
    const examKey = `${STORAGE_PREFIX}history_${attempt.examId}`;
    const examHist: Chuong8ExamAttempt[] = JSON.parse(localStorage.getItem(examKey) || '[]');
    examHist.unshift(attempt);
    localStorage.setItem(examKey, JSON.stringify(examHist.slice(0, 30)));

    const allKey = `${STORAGE_PREFIX}history_all`;
    const allHist: Chuong8ExamAttempt[] = JSON.parse(localStorage.getItem(allKey) || '[]');
    allHist.unshift(attempt);
    localStorage.setItem(allKey, JSON.stringify(allHist.slice(0, 50)));

    const prog = getChuong8UserProgress();
    const curHigh = prog.highestScores[attempt.examId] || 0;
    if (attempt.score > curHigh) {
      prog.highestScores[attempt.examId] = attempt.score;
    }
    prog.xpPoints += Math.round(attempt.score * 10);
    localStorage.setItem(`${STORAGE_PREFIX}user_progress`, JSON.stringify(prog));
  } catch (e) {
    console.error('Error saving exam attempt:', e);
  }
}

export function saveChuong8ExamResult(examId: string, score: number, durationSeconds: number = 0) {
  saveChuong8ExamAttempt({
    id: `att_${Date.now()}`,
    examId,
    examTitle: examId,
    score,
    part1Score: 0,
    part2Score: 0,
    part3Score: 0,
    correctCount: 0,
    totalQuestions: 28,
    durationSeconds,
    tabSwitchCount: 0,
    date: new Date().toISOString(),
    formattedDate: new Date().toLocaleDateString('vi-VN'),
    answers: {}
  });
}

export function shuffleChuong8Exam(exam: Chuong8Exam): Chuong8Exam {
  if (!exam || !exam.questions) return exam;
  const p1 = exam.questions.filter(q => q.part === 1);
  const p2 = exam.questions.filter(q => q.part === 2);
  const p3 = exam.questions.filter(q => q.part === 3);

  const shuffleArr = (arr: any[]) => {
    const res = [...arr];
    for (let i = res.length - 1; i > 0; i--) {
      const j = Math.floor(Math.random() * (i + 1));
      [res[i], res[j]] = [res[j], res[i]];
    }
    return res;
  };

  const shuffledP1 = shuffleArr(p1);
  const shuffledP2 = shuffleArr(p2);
  const shuffledP3 = shuffleArr(p3);

  let num = 1;
  const renumbered: Chuong8Question[] = [];
  [shuffledP1, shuffledP2, shuffledP3].forEach(subList => {
    subList.forEach(q => {
      renumbered.push({
        ...q,
        number: num,
        displayNumber: num
      });
      num += 1;
    });
  });

  return {
    ...exam,
    questions: renumbered
  };
}

export function getChuong8RankTitle(xp: number): string {
  if (xp >= 500) return '🏅 Bậc Thầy Hóa Học 12';
  if (xp >= 300) return '🌟 Thủ Khoa Triển Vọng';
  if (xp >= 150) return '⚡ Dũng Sĩ Luyện Đề';
  if (xp >= 50)  return '🌱 Chiến Binh Tập Sự';
  return '📚 Tân Binh Khối 12';
}


export const getRankTitle = getChuong8RankTitle;

